import{_ as a,o as t,c as o,ag as n}from"./chunks/framework.Dk8PTAaz.js";const u=JSON.parse('{"title":"How the Navigation Flow Works","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/navigation-flow.md","filePath":"en/guide/navigation-flow.md","lastUpdated":1788616892000}'),s={name:"en/guide/navigation-flow.md"};function i(r,e,l,c,d,h){return t(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="how-the-navigation-flow-works" tabindex="-1">How the Navigation Flow Works <a class="header-anchor" href="#how-the-navigation-flow-works" aria-label="Permalink to &quot;How the Navigation Flow Works&quot;">​</a></h1><p>Understand what happens in a unix-router navigation from trigger to completion.</p><h2 id="flowchart" tabindex="-1">Flowchart <a class="header-anchor" href="#flowchart" aria-label="Permalink to &quot;Flowchart&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes one-dark-pro github-light vp-code" tabindex="0"><code><span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">flowchart TD</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	A[router.push / replace / relaunch] --&gt; B{Previous navigation?}</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	B -- yes --&gt; WAIT[Wait for completion]</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	WAIT --&gt; C</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	B -- no --&gt; C[matcher.resolve resolves target]</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	C --&gt; D{Duplicate navigation? push to same location}</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	D -- yes --&gt; DUP[Throw NAVIGATION_DUPLICATED]</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	D -- no --&gt; E[runBeforeEach global before guards]</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	E --&gt; F{Result?}</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	F -- abort/cancel --&gt; ABORT[Trigger onError + afterEach(fail)]</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	F -- redirect --&gt; REDIRECT{Depth exceeded?}</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	REDIRECT -- yes --&gt; CANCEL[Cancel navigation]</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	REDIRECT -- no --&gt; C</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	F -- allowed --&gt; G[runBeforeEnter route-local guard]</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	G --&gt; H[runBeforeResolve global resolve guards]</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	H --&gt; I[Call uni.* navigation API]</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	I --&gt; J{Success?}</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	J -- failure --&gt; APIERR[Rollback + trigger protection]</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	J -- success --&gt; K[Update currentRoute + runAfterEach]</span></span></code></pre></div><h2 id="execution-order-forward-navigation-push-replace-relaunch" tabindex="-1">Execution Order (Forward Navigation push / replace / relaunch) <a class="header-anchor" href="#execution-order-forward-navigation-push-replace-relaunch" aria-label="Permalink to &quot;Execution Order (Forward Navigation push / replace / relaunch)&quot;">​</a></h2><ol><li><strong>Concurrent queuing</strong>: waits for the previous navigation to complete.</li><li><strong>Resolve the target</strong>: <code>matcher.resolve(location)</code> produces a <code>RouteLocation</code>.</li><li><strong>Duplicate detection</strong>: <code>push</code> to the same location as the current one → <code>NAVIGATION_DUPLICATED</code>.</li><li><strong>Global before</strong> <code>beforeEach</code></li><li><strong>Route-local</strong> <code>beforeEnter</code> (if configured)</li><li><strong>Global resolve</strong> <code>beforeResolve</code></li><li><strong>Native navigation</strong>: dispatches <code>navigateTo/redirectTo/reLaunch/switchTab</code> based on <code>meta.isTab</code></li><li><strong>Post after completion</strong> <code>afterEach</code>, and update <code>currentRoute</code></li></ol><p>Any guard returning <code>false</code>/<code>Error</code>/a redirect will abort or reroute the navigation. The navigation is cancelled when the redirect depth exceeds <code>MAX_REDIRECT_DEPTH</code>.</p><h2 id="the-back-flow" tabindex="-1">The back Flow <a class="header-anchor" href="#the-back-flow" aria-label="Permalink to &quot;The back Flow&quot;">​</a></h2><p><code>router.back(delta)</code> is shorter:</p><ol><li>Wait for the previous navigation to complete</li><li>Compute the target page from the page stack</li><li><code>beforeEach</code> → <code>beforeResolve</code></li><li><code>uni.navigateBack(delta)</code></li><li>Sync <code>currentRoute</code> and trigger <code>afterEach</code></li></ol><h2 id="state-sync-syncroute" tabindex="-1">State Sync syncRoute <a class="header-anchor" href="#state-sync-syncroute" aria-label="Permalink to &quot;State Sync syncRoute&quot;">​</a></h2><p>uni-app x&#39;s physical back button, tab switches, and so on do <strong>not pass through the router</strong>. On <code>install</code>, a global mixin is injected that automatically calls <code>router.syncRoute()</code> on the page&#39;s <code>onShow</code>, rebuilding <code>currentRoute</code> from the page stack so that <code>useRoute()</code> always reflects the real page.</p><h2 id="cold-start-guardroute" tabindex="-1">Cold Start guardRoute <a class="header-anchor" href="#cold-start-guardroute" aria-label="Permalink to &quot;Cold Start guardRoute&quot;">​</a></h2><p>When a user enters a page directly (H5 URL / scene value / deeplink), the page is already loaded and the guards haven&#39;t run. <code>guardRoute()</code> re-runs the guard chain for the current route: if allowed it returns; if redirected it navigates; if aborted it triggers <code>onAbort</code>, which can redirect to a safe page.</p><h2 id="where-your-code-runs" tabindex="-1">Where Your Code Runs <a class="header-anchor" href="#where-your-code-runs" aria-label="Permalink to &quot;Where Your Code Runs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Your code</th><th>Step</th></tr></thead><tbody><tr><td><code>matcher.resolve</code> resolution</td><td>determines <code>to</code> (your <code>routes</code> config)</td></tr><tr><td><code>beforeEach</code></td><td>global before (after queueing, resolution, duplicate check)</td></tr><tr><td><code>beforeEnter</code></td><td>route-local before (after <code>beforeEach</code>)</td></tr><tr><td><code>beforeResolve</code></td><td>the last gate before the real navigation</td></tr><tr><td><code>uni.*</code> native navigation</td><td>internal scheduling (dispatched by <code>meta.isTab</code>)</td></tr><tr><td><code>afterEach</code> / <code>onRouteChange</code></td><td>after the navigation is committed</td></tr><tr><td><code>syncRoute</code></td><td>page <code>onShow</code>, rebuilds <code>currentRoute</code> from the page stack</td></tr></tbody></table><h2 id="internal-scheduling-at-a-glance" tabindex="-1">Internal Scheduling at a Glance <a class="header-anchor" href="#internal-scheduling-at-a-glance" aria-label="Permalink to &quot;Internal Scheduling at a Glance&quot;">​</a></h2><p>A simple <code>push</code> roughly undergoes (pseudo-code):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes one-dark-pro github-light vp-code" tabindex="0"><code><span class="line"><span>push(location)</span></span>
<span class="line"><span>  → if there is a pendingNavigation, wait for it (concurrent queueing)</span></span>
<span class="line"><span>  → matcher.resolve(location)                 // produce to</span></span>
<span class="line"><span>  → push to the same address?  → throw DUPLICATED</span></span>
<span class="line"><span>  → runBeforeEach(to, from)                   // global before</span></span>
<span class="line"><span>  → runBeforeEnter(config, to, from)          // route-local</span></span>
<span class="line"><span>  → runBeforeResolve(to, from)                // global resolve</span></span>
<span class="line"><span>  → navigateTo / switchTab / ...              // the real navigation</span></span>
<span class="line"><span>  → update currentRoute + runAfter(to, from)  // commit + after</span></span></code></pre></div><p>Key points:</p><ul><li>Before any real <code>uni.*</code> navigation, <code>to</code> has passed all guards.</li><li>Any guard returning a non-&quot;continue&quot; result returns early (<code>abort</code> / <code>redirect</code>) and never reaches the native navigation.</li><li><code>afterEach</code> fires after <code>currentRoute</code> is updated; <code>onRouteChange</code> listeners are notified here too.</li></ul>`,21)])])}const g=a(s,[["render",i]]);export{u as __pageData,g as default};
